// Experimental 3PL IRT. Item parameters and SAT-scale mapping are heuristic, not calibrated.
export const IRT_MODEL={name:'3PL MAP',window:20,priorSD:1.5,guessing:.25,parameterSource:'heuristic',calibrated:false,accuracyClaim:null,disclaimer:'Experimental practice estimate. No validated SAT accuracy or ±20-point guarantee.'};
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export function irtProbability(theta,{a=1.15,b=0,c=.25}={}){return clamp(c+(1-c)/(1+Math.exp(-a*(theta-b))),1e-8,1-1e-8);}
export function independentWindow(log,bank,limit=20){const map=new Map(bank.map(q=>[q.id,q])),seen=new Set(),eligible=[];for(const entry of log){if(seen.has(entry.id)||!map.has(entry.id))continue;seen.add(entry.id);if((entry.hints??0)>0)continue;eligible.push({...entry,item:map.get(entry.id)});}return eligible.slice(-limit);}
const scale=theta=>Math.round((200+600/(1+Math.exp(-theta/1.4)))/10)*10;
export function estimateAbility(responses){if(!responses.length)return null;const grid=[];let max=-Infinity;for(let i=0;i<=200;i++){const theta=-4+i*.04;let ll=-theta*theta/(2*IRT_MODEL.priorSD**2);for(const r of responses){const p=irtProbability(theta,r.item.irt??{b:{Easy:-1,Medium:0,Hard:1.2}[r.item.difficulty]});ll+=r.correct?Math.log(p):Math.log1p(-p);}grid.push({theta,ll});max=Math.max(max,ll);}let mass=0;for(const point of grid){point.weight=Math.exp(point.ll-max);mass+=point.weight;}let cumulative=0,lo=grid[0].theta,hi=grid.at(-1).theta,loFound=false,mean=0;const best=grid.reduce((a,b)=>a.ll>b.ll?a:b);for(const point of grid){const w=point.weight/mass;mean+=w*scale(point.theta);cumulative+=w;if(!loFound&&cumulative>=.025){lo=point.theta;loFound=true;}if(cumulative>=.975){hi=point.theta;break;}}// Compute moments across the complete posterior, independently of quantile traversal.
 mean=grid.reduce((s,p)=>s+p.weight/mass*scale(p.theta),0);const variance=grid.reduce((s,p)=>s+p.weight/mass*(scale(p.theta)-mean)**2,0);return{n:responses.length,theta:Number(best.theta.toFixed(2)),score:scale(best.theta),range:[scale(lo),scale(hi)],variance};}
export function predictScores(log,bank){const recent=independentWindow(log,bank),subjects=['Math','Reading & Writing'],sections={};for(const subject of subjects){const rows=recent.filter(r=>r.item.subject===subject);sections[subject]=rows.length>=5?estimateAbility(rows):{n:rows.length,score:null,range:null};}const domains={};for(const domain of [...new Set(bank.map(q=>q.domain))]){const rows=recent.filter(r=>r.item.domain===domain);domains[domain]=rows.length>=3?estimateAbility(rows):{n:rows.length,score:null,range:null};}const sufficient=recent.length>=20&&subjects.every(s=>sections[s].score!==null);let total=null,range=null;if(sufficient){total=sections.Math.score+sections['Reading & Writing'].score;const spread=1.96*Math.sqrt(sections.Math.variance+sections['Reading & Writing'].variance);range=[clamp(Math.floor((total-spread)/10)*10,400,1600),clamp(Math.ceil((total+spread)/10)*10,400,1600)];}return{model:IRT_MODEL,n:recent.length,total,range,sections,domains,ready:sufficient,minimum:'20 independent first responses, including at least 5 per section; 3 per domain for a domain proxy.',sampleIds:recent.map(r=>r.id),rangeMeaning:'Model-derived uncertainty only. This range does not include unknown SAT calibration error.'};}
